  "content": "<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cortes de YouTube</title>
    <!-- Tailwind CSS via CDN -->
    <script src="https://cdn.tailwindcss.com"></script>
    <!-- Google API (placeholder) -->
    <script src="https://accounts.google.com/gsi/client" async defer></script>
    <link rel="stylesheet" href="style.css" />
</head>
<body class="bg-gray-100 min-h-screen flex items-center justify-center p-4">
    <div class="bg-white rounded-lg shadow-lg p-6 w-full max-w-xl">
        <h1 class="text-2xl font-bold mb-4 text-center">Criador de Cortes do YouTube</h1>
        <!-- Botão de login (Google) – placeholder -->
        <div id="g_id_onload"
            data-client_id="YOUR_GOOGLE_CLIENT_ID"
            data-context="signin"
            data-ux_mode="popup"
            data-callback="handleCredentialResponse"
            data-auto_prompt="false">
        </div>
        <div class="flex justify-center mb-4" id="login-button-container">
            <div class="g_id_signin"
                data-type="standard"
                data-size="large"
                data-theme="outline"
                data-text="sign_in_with"
                data-shape="rectangular"
                data-logo_alignment="left">
            </div>
        </div>
        <form id="cut-form" class="space-y-4">
            <div>
                <label class="block text-sm font-medium text-gray-700" for="video-url">URL do vídeo</label>
                <input type="url" id="video-url" required class="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500" placeholder="https://www.youtube.com/watch?v=VIDEO_ID" />
            </div>
            <div class="grid grid-cols-2 gap-4">
                <div>
                    <label class="block text-sm font-medium text-gray-700" for="start-time">Início (segundos)</label>
                    <input type="number" id="start-time" min="0" required class="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500" placeholder="0" />
                </div>
                <div>
                    <label class="block text-sm font-medium text-gray-700" for="end-time">Fim (segundos)</label>
                    <input type="number" id="end-time" min="0" required class="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500" placeholder="60" />
                </div>
            </div>
            <button type="submit" class="w-full bg-indigo-600 text-white py-2 px-4 rounded hover:bg-indigo-700 transition">Gerar Corte</button>
        </form>
        <div id="result" class="mt-6 hidden">
            <h2 class="text-xl font-semibold mb-2">Pré‑visualização</h2>
            <div class="aspect-w-16 aspect-h-9 mb-4" id="preview-container">
                <iframe id="preview-iframe" class="w-full h-full rounded" frameborder="0" allowfullscreen></iframe>
            </div>
            <div class="flex items-center space-x-2">
                <input type="text" id="clip-link" readonly class="flex-1 rounded border-gray-300 p-2" />
                <button id="copy-button" class="bg-gray-200 hover:bg-gray-300 text-gray-800 py-1 px-3 rounded">Copiar</button>
            </div>
        </div>
    </div>
    <script src="script.js"></script>
</body>
</html>"
}
