  "content": "// script.js – lógica do criador de cortes do YouTube

// Função auxiliar: extrair o ID do vídeo a partir de diferentes formatos de URL
function extractVideoId(url) {
    try {
        const parsed = new URL(url);
        // URLs padrão (youtube.com/watch?v=ID)
        if (parsed.hostname.includes('youtube.com')) {
            return parsed.searchParams.get('v');
        }
        // URLs curtas (youtu.be/ID)
        if (parsed.hostname === 'youtu.be') {
            return parsed.pathname.slice(1);
        }
        // Embed URLs (youtube.com/embed/ID)
        if (parsed.pathname.startsWith('/embed/')) {
            return parsed.pathname.split('/')[2];
        }
        return null;
    } catch (e) {
        return null;
    }
}

// Manipulador do formulário
document.getElementById('cut-form').addEventListener('submit', function (e) {
    e.preventDefault();
    const url = document.getElementById('video-url').value.trim();
    const start = parseInt(document.getElementById('start-time').value, 10);
    const end = parseInt(document.getElementById('end-time').value, 10);

    const videoId = extractVideoId(url);
    if (!videoId) {
        alert('Não foi possível extrair o ID do vídeo. Verifique a URL.');
        return;
    }
    if (end <= start) {
        alert('O tempo de fim deve ser maior que o de início.');
        return;
    }

    // Monta a URL de embed com parâmetros start e end
    const embedUrl = `https://www.youtube.com/embed/${videoId}?start=${start}&end=${end}&autoplay=1`;

    // Atualiza preview
    const iframe = document.getElementById('preview-iframe');
    iframe.src = embedUrl;
    document.getElementById('result').classList.remove('hidden');

    // Link direto para o corte (usando parâmetros start/end)
    const clipLink = `https://www.youtube.com/watch?v=${videoId}&t=${start}s`;
    const linkInput = document.getElementById('clip-link');
    linkInput.value = clipLink;
});

// Copiar link para a área de transferência
document.getElementById('copy-button').addEventListener('click', function () {
    const linkInput = document.getElementById('clip-link');
    linkInput.select();
    linkInput.setSelectionRange(0, 99999); // para dispositivos móveis
    navigator.clipboard.writeText(linkInput.value).then(() => {
        alert('Link copiado!');
    }).catch(() => {
        alert('Falha ao copiar o link.');
    });
});

// Placeholder para o callback de login Google – pode ser implementado futuramente
function handleCredentialResponse(response) {
    console.log('Google credential response', response);
    // Aqui você poderia armazenar o token e habilitar funcionalidades que requerem autenticação.
}
"
}
